  "settings.email.change": ["Change email", "Cambiar correo", "Changer l'e-mail", "E-Mail ändern", "Cambia email", "Alterar e-mail", "メールアドレスを変更", "更改邮箱", "이메일 변경"],
  "settings.email.changed": ["Email address changed", "Dirección de correo cambiada", "Adresse e-mail modifiée", "E-Mail-Adresse geändert", "Indirizzo email modificato", "Endereço de e-mail alterado", "メールアドレスを変更しました", "邮箱地址已更改", "이메일 주소를 변경했어요"],
  "settings.password.title": ["Password", "Contraseña", "Mot de passe", "Passwort", "Password", "Senha", "パスワード", "密码", "비밀번호"],
  "settings.password.description": ["Changing it logs you out of every other browser and device.", "Al cambiarla se cierra la sesión en todos los demás navegadores y dispositivos.", "Le changer te déconnecte de tous les autres navigateurs et appareils.", "Eine Änderung meldet dich in allen anderen Browsern und auf allen anderen Geräten ab.", "Cambiandola verrai disconnesso da tutti gli altri browser e dispositivi.", "Alterá-la encerra a sessão em todos os outros navegadores e dispositivos.", "変更すると、他のすべてのブラウザとデバイスからログアウトされます。", "更改后，你会在其他所有浏览器和设备上退出登录。", "변경하면 다른 모든 브라우저와 기기에서 로그아웃돼요."],
  "settings.password.current": ["Current password", "Contraseña actual", "Mot de passe actuel", "Aktuelles Passwort", "Password attuale", "Senha atual", "現在のパスワード", "当前密码", "현재 비밀번호"],
  "settings.password.new": ["New password", "Contraseña nueva", "Nouveau mot de passe", "Neues Passwort", "Nuova password", "Nova senha", "新しいパスワード", "新密码", "새 비밀번호"],
  "settings.password.min": ["At least 8 characters.", "Al menos 8 caracteres.", "Au moins 8 caractères.", "Mindestens 8 Zeichen.", "Almeno 8 caratteri.", "Pelo menos 8 caracteres.", "8文字以上。", "至少 8 个字符。", "8자 이상."],
  "settings.password.again": ["New password again", "Repite la contraseña nueva", "Nouveau mot de passe (confirmation)", "Neues Passwort wiederholen", "Ripeti la nuova password", "Repita a nova senha", "新しいパスワード（確認）", "再次输入新密码", "새 비밀번호 확인"],
  "settings.password.mismatch": ["The two new passwords don't match", "Las dos contraseñas nuevas no coinciden", "Les deux nouveaux mots de passe ne correspondent pas", "Die beiden neuen Passwörter stimmen nicht überein", "Le due nuove password non coincidono", "As duas senhas novas não coincidem", "新しいパスワードが一致しません", "两次输入的新密码不一致", "새 비밀번호 두 개가 일치하지 않아요"],
  "settings.password.change": ["Change password", "Cambiar contraseña", "Changer le mot de passe", "Passwort ändern", "Cambia password", "Alterar senha", "パスワードを変更", "更改密码", "비밀번호 변경"],
  "settings.password.changed": ["Password changed. Your other devices were logged out.", "Contraseña cambiada. Se cerró la sesión en tus otros dispositivos.", "Mot de passe modifié. Tes autres appareils ont été déconnectés.", "Passwort geändert. Deine anderen Geräte wurden abgemeldet.", "Password modificata. Gli altri tuoi dispositivi sono stati disconnessi.", "Senha alterada. Seus outros dispositivos foram desconectados.", "パスワードを変更しました。他のデバイスはログアウトされました。", "密码已更改，你的其他设备已退出登录。", "비밀번호를 변경했어요. 다른 기기는 로그아웃됐어요."],
